INSERT INTO `jottings` (`id`, `english`, `chinese`, `create_time`, `reviewed`) VALUES (1,'when it comes to A','当说到A','2025-11-22 23:25:59',0),(2,'quite a few','固定短语，意为“相当多','2025-11-24 16:57:14',0),(3,'take the time to do something','(特意)花费时间去做某事','2025-11-30 16:59:18',0),(4,'common sense','常识','2025-12-09 15:51:02',0),(5,'go hand in hand','密切相关','2025-12-09 15:51:26',0),(6,'be prone to','易于......','2025-12-09 15:51:54',0),(7,'it turns out that','事实证明','2025-12-09 15:52:36',0),(8,'the same boring old advice that......','老生常谈','2025-12-09 15:53:07',0),(9,'after all','毕竟','2025-12-09 15:53:25',0),(10,'The challenges are enormous, even if everyone is pulling in the same direction.','即使每个人都朝着同一个方向努力，挑战也是巨大的','2025-12-09 15:55:14',0),(11,'be named to','被任命','2025-12-09 15:55:48',0),(12,'hang out somewhere','在某处闲逛','2025-12-09 15:56:12',0);
/*!40000 ALTER TABLE `jottings` ENABLE KEYS */;
